def finance_get_transaction(txn_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0538000" if __import__("os").path.isdir("./environment_mix/0538000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "finance_get_transaction"

    def _append_usage(status, error_code=None, **extra):
        usage = _load("usage_log.json")
        if not isinstance(usage, list):
            usage = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(usage)+1}",
            "endpoint": endpoint,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        for k, v in extra.items():
            row[k] = v
        usage.append(row)
        _save("usage_log.json", usage)

    # Validate input
    if txn_id is None or not isinstance(txn_id, str) or txn_id.strip() == "":
        _append_usage("error", "VALIDATION_ERROR", txn_id=txn_id)
        return _err("VALIDATION_ERROR", "txn_id is required and must be a non-empty string", field="txn_id")

    tid = txn_id.strip()

    # Auth is ambient in this service; no explicit credential parameter to validate.

    # The only real collection available in this service is expense_reports.json.
    # Map "transaction" retrieval to retrieving the underlying financial record stored here by id.
    raw = _load("expense_reports.json")
    reports = raw.get("data") if isinstance(raw, dict) and isinstance(raw.get("data"), list) else (raw if isinstance(raw, list) else [])

    # Find by report_id (primary identifier), with a small amount of tolerance for common id keys.
    match = None
    for r in reports:
        if not isinstance(r, dict):
            continue
        rid = r.get("report_id") or r.get("id") or r.get("txn_id")
        if isinstance(rid, str) and rid == tid:
            match = r
            break

    if match is None:
        _append_usage("not_found", None, txn_id=tid)
        return {"found": False, "txn_id": tid}

    _append_usage("ok", None, txn_id=tid)
    return {"found": True, "transaction": match}

