def finance_submit_report(employee, total, items=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0538000" if __import__("os").path.isdir("./environment_mix/0538000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "finance_submit_report"

    def _log(status, error_code=None):
        usage = _load("usage_log.json")
        if not isinstance(usage, list):
            usage = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(usage)+1}",
            "endpoint": endpoint,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "employee": employee if isinstance(employee, str) else None,
        }
        if error_code:
            row["error_code"] = error_code
        usage.append(row)
        _save("usage_log.json", usage)

    # validation: employee
    if employee is None or not isinstance(employee, str) or employee.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "employee is required and must be a non-empty string", field="employee")
    employee = employee.strip()
    # simple email-like validation
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", employee):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "employee must be a valid email identifier", field="employee")

    # validation: total
    if total is None or not isinstance(total, (int, float)) or isinstance(total, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "total is required and must be a number", field="total")
    total_val = float(total)
    if total_val < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "total must be non-negative", field="total")

    # validation: items
    if items is None:
        items_val = 1
    else:
        if not isinstance(items, int) or isinstance(items, bool):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "items must be an integer when provided", field="items")
        if items < 0:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "items must be non-negative", field="items")
        items_val = items

    reps = _load("expense_reports.json")
    if not isinstance(reps, list):
        reps = []

    # conflict rule (lightweight): prevent exact duplicate pending/submitted for same employee+total+items
    for r in reps:
        try:
            if (
                r.get("employee") == employee
                and float(r.get("total")) == total_val
                and int(r.get("items")) == items_val
                and r.get("status") in ("pending", "submitted")
            ):
                _log("error", "CONFLICT")
                return _err("CONFLICT", "a similar report is already pending/submitted", report_id=r.get("report_id"))
        except Exception:
            # ignore malformed existing rows
            pass

    # generate report_id: rep-<n> where n is max numeric suffix + 1
    max_n = 0
    for r in reps:
        rid = r.get("report_id")
        if isinstance(rid, str) and rid.startswith("rep-"):
            suf = rid[4:]
            if suf.isdigit():
                max_n = max(max_n, int(suf))
    report_id = f"rep-{max_n + 1}"

    now = datetime.datetime.utcnow().isoformat() + "Z"
    rec = {
        "report_id": report_id,
        "employee": employee,
        "status": "submitted",
        "total": total_val,
        "items": items_val,
        "created_at": now,
        "updated_at": now,
    }

    reps.append(rec)
    _save("expense_reports.json", reps)

    _log("ok")
    return {"report": rec}
